def pancake_sort(nums):
    arr = list(nums)
    n = len(arr)
    for size in range(n, 1, -1):
        # Find the index of the maximum element in arr[0:size]
        max_idx = 0
        for i in range(1, size):
            if arr[i] > arr[max_idx]:
