def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        if n <= 1:
            return 0
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total

    result = 0
    for num in range(2, limit + 1):
        partner = sum_of_divisors(num)
        if partner != num and sum_of_divisors(partner) == num:
            result += num
    return result

