def pancake_sort(nums):
    arr = list(nums)
    n = len(arr)
    for size in range(n, 1, -1):
        # Find the index of the maximum element in arr[0:size]
        max_idx = 0
        for i in range(1, size):
            if arr[i] > arr[max_idx]:
                max_idx = i
        if max_idx != size - 1:
            # Flip to bring max element to front
            arr[:max_idx + 1] = arr[:max_idx + 1][::-1]
            # Flip to send max element to its correct position
            arr[:size] = arr[:size][::-1]
    return arr

